"use strict";
// Compiled natively. The whole island module in a `var`: a method called
// and a class constructed while this module evaluates, the results stored
// and exported, and the binding used again inside functions.
var pantry = require("pantry");

var first = pantry.find("salt");
var jar = new pantry.Jar("flour", 3);

exports.firstLabel = function firstLabel() {
  return first.label;
};
exports.jarText = function jarText() {
  return jar.describe() + "/" + pantry.find("rice").label + "/" + pantry.lookups();
};
exports.grams = function grams(names) {
  return names.map(function (name) {
    return pantry.find(name).grams;
  });
};
exports.missing = function missing(name) {
  try {
    return pantry.find(name).label;
  } catch (e) {
    return e instanceof RangeError ? "RangeError: " + e.message : "other";
  }
};
